package com.example.metadata;

import java.util.List;
import java.util.Map;

import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.chat.metadata.ChatResponseMetadata;
import org.springframework.ai.chat.metadata.RateLimit;
import org.springframework.ai.chat.metadata.Usage;
import org.springframework.ai.chat.model.ChatResponse;
import org.springframework.ai.document.Document;
import org.springframework.ai.reader.TextReader;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.core.io.ClassPathResource;

@SpringBootApplication
public class MetadataApplication {

    public static void main(String[] args) {
        SpringApplication.run(MetadataApplication.class, args);
    }

    @Bean
    CommandLineRunner demo(ChatClient.Builder chatClientBuilder) {
        return args -> {
            ChatClient chatClient = chatClientBuilder.build();

            ChatResponse chatResponse = chatClient.prompt()
                    .user("What is Spring AI metadata?")
                    .call()
                    .chatResponse();

            ChatResponseMetadata metadata = chatResponse.getMetadata();
            Usage usage = metadata.getUsage();

            System.out.println("Model: " + metadata.getModel());
            System.out.println("Prompt tokens: " + usage.getPromptTokens());
            System.out.println("Completion tokens: " + usage.getCompletionTokens());
            System.out.println("Total tokens: " + usage.getTotalTokens());

            RateLimit rateLimit = metadata.getRateLimit();
            if (rateLimit != null) {
                System.out.println("Requests remaining: " + rateLimit.getRequestsRemaining());
                System.out.println("Tokens remaining: " + rateLimit.getTokensRemaining());
            }

            String answer = chatResponse.getResult().getOutput().getText();
            System.out.println("Answer: " + answer);

            TextReader reader = new TextReader(new ClassPathResource("documents/policy.txt"));
            reader.getCustomMetadata().put("department", "HR");
            reader.getCustomMetadata().put("security_level", "confidential");

            List<Document> documents = reader.get();
            for (Document document : documents) {
                System.out.println("Loaded metadata: " + document.getMetadata());
                System.out.println("Loaded text: " + document.getText());
            }

            Document manual = new Document(
                    "Here is the body text of the document.",
                    Map.of("author", "Jane Doe", "year", 2026));
            System.out.println("Manual metadata: " + manual.getMetadata());
            System.out.println("Manual text: " + manual.getText());
        };
    }
}

package com.example.deterministic;

import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.chat.model.ChatResponse;
import org.springframework.ai.openai.OpenAiChatOptions;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
