@SpringBootApplication
public class DeterministicChatApplication {

    public static void main(String[] args) {
        SpringApplication.run(DeterministicChatApplication.class, args);
    }

    @Bean
    CommandLineRunner demo(ChatClient.Builder builder) {
        OpenAiChatOptions options = OpenAiChatOptions.builder()
                .model("gpt-4o")
                .temperature(0.0)
                .seed(12345)
                .build();

        ChatClient chatClient = builder
                .defaultOptions(options)
                .build();

        return args -> {
            ChatResponse response = chatClient.prompt()
                    .user("Name three ways Spring AI reduces response randomness.")
                    .options(options)
                    .call()
                    .chatResponse();

            System.out.println(response.getResult().getOutput().getText());
        };
    }
}

