package com.example.deterministic;

import org.springframework.ai.chat.client.ChatClient;
import org.springframework.ai.openai.OpenAiChatOptions;

public class DeterministicEntityCall {

    public record Grade(int score, String rationale) {
    }

    private final ChatClient chatClient;
    private final OpenAiChatOptions options;

    public DeterministicEntityCall(ChatClient.Builder builder) {
        this.options = OpenAiChatOptions.builder()
                .model("gpt-4o")
                .temperature(0.0)
                .seed(12345)
                .build();
        this.chatClient = builder.defaultOptions(options).build();
    }

    public Grade grade(String answer) {
        RuntimeException lastFailure = null;
        for (int attempt = 1; attempt <= 2; attempt++) {
            try {
                Grade grade = chatClient.prompt()
                        .user("Grade this answer from 0 to 5: " + answer)
                        .options(options)
                        .call()
                        .entity(Grade.class);
                if (grade.score() < 0 || grade.score() > 5) {
                    throw new IllegalStateException("Score is outside 0 to 5.");
                }
                return grade;
            } catch (RuntimeException exception) {
                lastFailure = exception;
            }
        }
        throw lastFailure;
    }

    public static void main(String[] args) {
        System.out.println("Run this type inside a Spring AI application.");
        System.out.println("Retry with the same temperature and seed. Do not compare the full paragraph.");
    }
}

