@Component
public class ProductionToolFilter implements McpToolFilter {

    @Override
    public boolean test(McpConnectionInfo connectionInfo, Tool tool) {
        String server = connectionInfo.initializeResult().serverInfo().name();
        if ("sandbox".equals(server)) {
            return false;
        }
        return tool.name() == null || !tool.name().startsWith("experimental_");
    }
}

