package com.example.memory;

import org.springframework.ai.chat.memory.ChatMemory;
import org.springframework.stereotype.Service;

@Service
public class ForgetService {

    private final ChatMemory chatMemory;
    private final ConversationIndex index;

    public ForgetService(ChatMemory chatMemory, ConversationIndex index) {
        this.chatMemory = chatMemory;
        this.index = index;
    }

    public void forget(String userId, String chatId) {
        String conversationId = index.ownedBy(userId, chatId);
        chatMemory.clear(conversationId);
        index.delete(userId, chatId);
    }
}
